#include "fedspatial/gpu_context.hpp"
#include "fedspatial/nworker_15k_figure1_config.hpp"
#include <cmath>
#include <iostream>
#include <stdexcept>
#include <vector>
using namespace fedspatial;
static void ck(cudaError_t e){if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}
static void cb(cublasStatus_t e){if(e!=CUBLAS_STATUS_SUCCESS)throw std::runtime_error("cublas failure");}
static WorkerInput worker(int n){Matrix s(n,2),z(n,1),x(n,1);for(int i=0;i<n;++i){s(i,0)=.001*(i%997);s(i,1)=.003*(i%313);z(i,0)=std::sin(.01*i);x(i,0)=1.;}return{s,z,x};}
static Matrix knots(int m){Matrix k(m,2);for(int i=0;i<m;++i){k(i,0)=.002*(i%499);k(i,1)=.004*(i%211);}return k;}
static double vd(const std::vector<double>&a,const std::vector<double>&b){double e=0;for(size_t i=0;i<a.size();++i)e=std::max(e,std::abs(a[i]-b[i]));return e;}
static bool fn(const std::vector<double>&a){for(double x:a)if(!std::isfinite(x))return false;return true;}
static bool run(int n,int m){
 Matrix g(1,1),mu(m,1),sig(m,m);g(0,0)=.1;for(int i=0;i<m;++i)sig(i,i)=1.;GlobalParameters p{g,mu,sig,.25,1.,.11};GpuContext c(0);c.set_local_solve_configuration({LocalSolveStrategy::dense_inverse_gemm,512ull<<20});auto wi=worker(n);auto ki=knots(m);auto s=build_device_mu_sigma_local(c,wi,ki,p);auto host=download_device_mu_sigma_local(c,s);auto cpu=solve_spd(host.M,identity(n));
 // Build the exact separately-owned production cache; the second call is its
 // explicit reuse check.  The solve oracle below uses this same W/scratch.
 build_device_local_dense_w_for_test(c,s);build_device_local_dense_w_for_test(c,s);auto&r=const_cast<RegionGpuState&>(c.region());size_t nn=size_t(n)*n;std::vector<double>w(nn),guard(4);ck(cudaMemcpyAsync(w.data(),r.local_dense_w,nn*sizeof(double),cudaMemcpyDeviceToHost,c.stream()));ck(cudaMemcpyAsync(&guard[0],r.local_dense_w_raw,sizeof(double),cudaMemcpyDeviceToHost,c.stream()));ck(cudaMemcpyAsync(&guard[1],r.local_dense_w_raw+r.local_dense_w_capacity+1,sizeof(double),cudaMemcpyDeviceToHost,c.stream()));ck(cudaStreamSynchronize(c.stream()));Matrix wm(n,n);wm.a=w;auto mw=matmul(host.M,wm);double ri=0,fr=0,sy=0;for(int i=0;i<n;++i)for(int j=0;j<n;++j){double v=mw(i,j)-(i==j);ri=std::max(ri,std::abs(v));fr+=v*v;sy=std::max(sy,std::abs(wm(i,j)-wm(j,i)));}
 // Explicit multi-RHS oracle: streamed L^-T L^-1 versus W GEMM.
 int cols=std::min(7,m);std::vector<double>x(size_t(n)*cols),a(x.size()),b(x.size());for(size_t i=0;i<x.size();++i)x[i]=std::sin(.017*i);double *da{},*db{};ck(cudaMalloc(&da,x.size()*sizeof(double)));ck(cudaMalloc(&db,x.size()*sizeof(double)));ck(cudaMemcpyAsync(da,x.data(),x.size()*sizeof(double),cudaMemcpyHostToDevice,c.stream()));ck(cudaMemcpyAsync(db,x.data(),x.size()*sizeof(double),cudaMemcpyHostToDevice,c.stream()));double one=1,zero=0,lo=0x1.23456789abcp+17,hi=-0x1.987654321fedcp-19;cb(cublasDtrsm(c.cublas(),CUBLAS_SIDE_LEFT,CUBLAS_FILL_MODE_LOWER,CUBLAS_OP_N,CUBLAS_DIAG_NON_UNIT,n,cols,&one,s.chol_M,n,da,n));cb(cublasDtrsm(c.cublas(),CUBLAS_SIDE_LEFT,CUBLAS_FILL_MODE_LOWER,CUBLAS_OP_T,CUBLAS_DIAG_NON_UNIT,n,cols,&one,s.chol_M,n,da,n));if(!r.local_dense_solve_raw){ck(cudaMalloc(&r.local_dense_solve_raw,(x.size()+2)*sizeof(double)));r.local_dense_solve=r.local_dense_solve_raw+1;r.local_dense_solve_capacity=x.size();}ck(cudaMemcpyAsync(r.local_dense_solve_raw,&lo,sizeof(double),cudaMemcpyHostToDevice,c.stream()));ck(cudaMemcpyAsync(r.local_dense_solve_raw+r.local_dense_solve_capacity+1,&hi,sizeof(double),cudaMemcpyHostToDevice,c.stream()));cb(cublasDgemm(c.cublas(),CUBLAS_OP_N,CUBLAS_OP_N,n,cols,n,&one,r.local_dense_w,n,db,n,&zero,r.local_dense_solve,n));ck(cudaMemcpyAsync(db,r.local_dense_solve,x.size()*sizeof(double),cudaMemcpyDeviceToDevice,c.stream()));ck(cudaMemcpyAsync(a.data(),da,x.size()*sizeof(double),cudaMemcpyDeviceToHost,c.stream()));ck(cudaMemcpyAsync(b.data(),db,x.size()*sizeof(double),cudaMemcpyDeviceToHost,c.stream()));ck(cudaMemcpyAsync(&guard[2],r.local_dense_solve_raw,sizeof(double),cudaMemcpyDeviceToHost,c.stream()));ck(cudaMemcpyAsync(&guard[3],r.local_dense_solve_raw+r.local_dense_solve_capacity+1,sizeof(double),cudaMemcpyDeviceToHost,c.stream()));ck(cudaStreamSynchronize(c.stream()));cudaFree(da);cudaFree(db);double se=vd(a,b),we=max_abs_diff(wm,cpu);bool rz=guard[0]==lo&&guard[1]==hi&&guard[2]==lo&&guard[3]==hi;
 // A rebuilt in-place factor must rebuild W, while the production call above reused it.
 auto builds=r.local_dense_w_builds,reuses=r.local_dense_w_reuses;p.alpha=.93;auto s2=build_device_mu_sigma_local(c,wi,ki,p);build_device_local_dense_w_for_test(c,s2);auto h2=download_device_mu_sigma_local(c,s2);std::vector<double>w2(nn);ck(cudaMemcpyAsync(w2.data(),r.local_dense_w,nn*sizeof(double),cudaMemcpyDeviceToHost,c.stream()));ck(cudaStreamSynchronize(c.stream()));Matrix w2m(n,n);w2m.a=w2;double ie=max_abs_diff(w2m,solve_spd(h2.M,identity(n)));bool cache=r.local_dense_w_builds>builds&&reuses>0;bool ok=we<=1e-8&&ri<=1e-8&&sy<=1e-8&&fn(w)&&fn(a)&&fn(b)&&se<=1e-8&&rz&&ie<=1e-8&&cache;
 std::cout<<"DENSE_W n="<<n<<" m="<<m<<" W_CPU_MAX_ABS="<<we<<" W_SYMMETRY="<<sy<<" MW_I_INF="<<ri<<" MW_I_FRO="<<std::sqrt(fr)<<" FINITE="<<(fn(w)&&fn(a)&&fn(b)?"PASS":"FAIL")<<" RED_ZONE="<<(rz?"PASS":"FAIL")<<" VECTOR_MULTI_RHS_MAX_ABS="<<se<<" CACHE_INVALIDATE_W_CPU_MAX_ABS="<<ie<<" CACHE_REBUILD_REUSE="<<(cache?"PASS":"FAIL")<<" BUILDS="<<r.local_dense_w_builds<<" REUSES="<<r.local_dense_w_reuses<<" RESULT="<<(ok?"PASS":"FAIL")<<'\n';return ok;
}
int main(){try{setenv("CUDA_VISIBLE_DEVICES",NWorker15kFigure1Config::gv100_uuid_0,1);bool ok=true;const char* only=std::getenv("FEDSPATIAL_DENSE_W_ONLY_LAST");for(auto nm:std::array<std::array<int,2>,4>{{{{128,64}},{{500,100}},{{1000,100}},{{1000,256}}}}){if(only&&only[0]&&(nm[0]!=1000||nm[1]!=256))continue;ok&=run(nm[0],nm[1]);}std::cout<<"DENSE_W_DIRECT_PARITY="<<(ok?"PASS":"FAIL")<<'\n';return ok?0:1;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
